using sv_767abebdfcbc408987faac3f7cbb0e67.Models;

namespace sv_767abebdfcbc408987faac3f7cbb0e67.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Spaghetti Carbonara", "Classic Roman pasta with eggs, pecorino, guanciale, and black pepper.", 30),
            new(2, "Margherita Pizza", "Traditional Neapolitan pizza with tomato, mozzarella, and fresh basil.", 45),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream.", 40),
            new(4, "Risotto alla Milanese", "Creamy saffron-infused Arborio rice from Milan.", 35),
        },
        [2] = new List<Recipe>
        {
            new(5, "Chicken Tikka Masala", "Marinated chicken in a rich, spiced tomato-cream sauce.", 50),
            new(6, "Palak Paneer", "Fresh spinach curry with cubes of soft paneer cheese.", 35),
            new(7, "Biryani", "Fragrant basmati rice layered with spiced meat and caramelized onions.", 60),
            new(8, "Samosa", "Crispy pastry filled with spiced potatoes and peas.", 45),
        },
        [3] = new List<Recipe>
        {
            new(9, "Sushi Rolls", "Vinegared rice and fresh fish wrapped in nori seaweed.", 50),
            new(10, "Ramen", "Rich pork bone broth with wheat noodles, chashu, and soft-boiled egg.", 120),
            new(11, "Tempura", "Lightly battered and deep-fried shrimp and vegetables.", 25),
            new(12, "Miso Soup", "Dashi broth with dissolved miso paste, tofu, and wakame seaweed.", 15),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_767abebdfcbc408987faac3f7cbb0e67.Models
@using sv_767abebdfcbc408987faac3f7cbb0e67.Services
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav style="margin-bottom: 1rem;">
    <a href="/recipes/1?sort=@Sort">Italian</a> |
    <a href="/recipes/2?sort=@Sort">Indian</a> |
    <a href="/recipes/3?sort=@Sort">Japanese</a>
</nav>

<div style="margin-bottom: 1rem;">
    <label>
        Sort:
        <select @onchange="OnSortChanged" value="@Sort">
            <option value="newest">Newest</option>
            <option value="popular">Popular</option>
        </select>
    </label>
</div>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes...</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in GetSortedRecipes())
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload data when cuisine changes, not when sort changes
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        await CancelPendingRequestAsync();

        _cts = new CancellationTokenSource();
        var cancellationToken = _cts.Token;

        // If we already have data on screen, show refreshing indicator instead of full loading
        if (_recipes is not null)
        {
            _isRefreshing = true;
        }

        _errorMessage = null;
        var cuisineId = CuisineId;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(cuisineId, cancellationToken);

            if (cancellationToken.IsCancellationRequested)
            {
                return;
            }

            _recipes = results;
            _loadedCuisineId = cuisineId;
        }
        catch (OperationCanceledException)
        {
            // Request was cancelled (user navigated away or changed cuisine) — do nothing
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "The request timed out. Please check your connection and try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private IEnumerable<Recipe> GetSortedRecipes()
    {
        if (_recipes is null)
        {
            return Enumerable.Empty<Recipe>();
        }

        return string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? _recipes.OrderBy(r => r.PrepTimeMinutes)
            : _recipes.OrderByDescending(r => r.Id);
    }

    private async Task Retry()
    {
        _errorMessage = null;
        await LoadRecipesAsync();
    }

    private void OnSortChanged(ChangeEventArgs e)
    {
        Sort = e.Value?.ToString() ?? "newest";
        Navigation.NavigateTo($"/recipes/{CuisineId}?sort={Sort}");
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

